 expected constant jsonb := $history_scope_data$[{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":0,"owner":"postgres","config":["search_path=public, pg_temp"],"strict":false,"definer":false,"returns":"trigger","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"change_history_immutable()","definition":"\u0043REATE OR REPLACE FUNCTION public.change_history_immutable()\n RETURNS trigger\n LANGUAGE plpgsql\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nBEGIN RAISE EXCEPTION 'change_history is append-only'; END $function$\n","volatility":"v","definition_md5":"759a4591272575853e10c14d55df99d6","acl_values":["=X/postgres","postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"578cf538eeb44be63e0fe9fec2d98a89"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":0,"owner":"postgres","config":["search_path=public"],"strict":false,"definer":true,"returns":"jsonb","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"pos_sync_bootstrap_scoped(text,text,text,text,text,integer,integer)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_bootstrap_scoped(p_organization_id text, p_branch_id text, p_terminal_id text, p_table text, p_after_cursor text DEFAULT NULL::text, p_history_days integer DEFAULT 90, p_limit integer DEFAULT 500)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\nDECLARE v_rows jsonb:='[]'::jsonb; v_cursor text; v_me public.app_users%ROWTYPE;\nBEGIN PERFORM public.pos_sync_validate_read_scope(p_organization_id,p_branch_id,p_terminal_id); IF auth.role()<>'service_role' THEN SELECT * INTO v_me FROM public.app_users WHERE auth_user_id=auth.uid() AND is_active=true LIMIT 1;\n IF v_me.id IS NULL OR NOT (v_me.role='admin' OR COALESCE((v_me.permissions->>'can_manage_sync_backup')::boolean,false)) THEN RAISE EXCEPTION 'SYNC_FORBIDDEN'; END IF;\n IF NOT (v_me.role='admin' OR v_me.store_id IS NULL OR v_me.store_id=p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; END IF;\n CASE p_table WHEN 'coupon_campaigns' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"coupon_campaigns\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'shifts' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"shifts\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'issued_vouchers' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"issued_vouchers\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'activity_events' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"activity_events\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'app_users' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"app_users\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'audit_logs' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"audit_logs\" x WHERE (x.store_id::text=p_branch_id) AND (p_history_days>=7300 OR x.\"created_at\">=now()-make_interval(days=>GREATEST(p_history_days,30))) AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'booking_payments' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"booking_payments\" x WHERE (EXISTS(SELECT 1 FROM public.\"bookings\" p WHERE p.\"id\"::text=x.\"booking_id\"::text AND p.store_id::text=p_branch_id))  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'bookings' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"bookings\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'branch_telemetry' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('terminal_id',x.\"terminal_id\")::text cursor,x row_data FROM public.\"branch_telemetry\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('terminal_id',x.\"terminal_id\")::text>p_after_cursor) ORDER BY jsonb_build_object('terminal_id',x.\"terminal_id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'cashiers' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"cashiers\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'coupon_events' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"coupon_events\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'drawer_events' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"drawer_events\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'held_orders' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"held_orders\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'integration_settings' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"integration_settings\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'item_activity_logs' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"item_activity_logs\" x WHERE (x.store_id::text=p_branch_id) AND (p_history_days>=7300 OR x.\"created_at\">=now()-make_interval(days=>GREATEST(p_history_days,30))) AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'member_verifications' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"member_verifications\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'members' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) - ARRAY['auth_user_id']::text[] ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"members\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'membership_tiers' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"membership_tiers\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'offline_sync_audit_log' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"offline_sync_audit_log\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'payment_transactions' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"payment_transactions\" x WHERE (x.store_id::text=p_branch_id) AND (p_history_days>=7300 OR x.\"created_at\">=now()-make_interval(days=>GREATEST(p_history_days,30))) AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'payment_types' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"payment_types\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'pin_attempts' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('key',x.\"key\")::text cursor,x row_data FROM public.\"pin_attempts\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('key',x.\"key\")::text>p_after_cursor) ORDER BY jsonb_build_object('key',x.\"key\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'pos_settings' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"pos_settings\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'product_barcodes' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"product_barcodes\" x WHERE (EXISTS(SELECT 1 FROM public.\"products\" p WHERE p.\"id\"::text=x.\"product_id\"::text AND public.product_available_in_catalogue(p.id,p_branch_id)))  AND (p_after_cursor IS NULL OR x.\"id\">((p_after_cursor::jsonb)->>'id')::uuid) ORDER BY x.\"id\" LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'product_categories' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"product_categories\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'products' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"products\" x WHERE (public.product_available_in_catalogue(x.id,p_branch_id))  AND (p_after_cursor IS NULL OR x.\"id\">((p_after_cursor::jsonb)->>'id')::uuid) ORDER BY x.\"id\" LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'promotions' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"promotions\" x WHERE ((x.foc_product_id IS NULL OR EXISTS(SELECT 1 FROM public.\"products\" p WHERE p.\"id\"::text=x.\"foc_product_id\"::text AND public.product_available_in_catalogue(p.id,p_branch_id))))  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'public_flags' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('key',x.\"key\")::text cursor,x row_data FROM public.\"public_flags\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('key',x.\"key\")::text>p_after_cursor) ORDER BY jsonb_build_object('key',x.\"key\")::text LIMIT LEAST(GREATEST(p_lim