_object('id',x.\"id\")::text cursor,x row_data FROM public.\"shift_notifications\" x WHERE (x.store_id::text=p_branch_id) AND (p_history_days>=7300 OR x.\"created_at\">=now()-make_interval(days=>GREATEST(p_history_days,30))) AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'entity_status_history' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"entity_status_history\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'nav_pins' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"nav_pins\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'store_groups' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"store_groups\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'change_history' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"change_history\" x WHERE (true)  AND (p_after_cursor IS NULL OR x.\"id\">((p_after_cursor::jsonb)->>'id')::uuid) ORDER BY x.\"id\" LIMIT LEAST(GREATEST(p_limit,10),2000)) page; ELSE RAISE EXCEPTION 'SYNC_TABLE_FORBIDDEN'; END CASE;\n RETURN jsonb_build_object('rows',v_rows,'cursor',CASE WHEN jsonb_array_length(v_rows)>=LEAST(GREATEST(p_limit,10),2000) THEN v_cursor ELSE NULL END);\nEND $function$\n","volatility":"v","definition_md5":"b4306345e37e638c610e8484a479c510","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"b4306345e37e638c610e8484a479c510"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":0,"owner":"postgres","config":["search_path=public, pg_temp"],"strict":false,"definer":true,"returns":"jsonb","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"pos_sync_bootstrap(text,text,text,text,text,integer,integer)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_bootstrap(p_organization_id text, p_branch_id text, p_terminal_id text, p_table text, p_after_cursor text DEFAULT NULL::text, p_history_days integer DEFAULT 90, p_limit integer DEFAULT 500)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE v_rows jsonb:='[]'::jsonb; v_cursor text; v_me public.app_users%ROWTYPE;\nBEGIN\n  IF p_table <> 'issued_vouchers' THEN\n    RETURN public.pos_sync_bootstrap_scoped(\n      p_organization_id,p_branch_id,p_terminal_id,p_table,p_after_cursor,p_history_days,p_limit\n    );\n  END IF;\n  PERFORM public.pos_sync_validate_read_scope(p_organization_id,p_branch_id,p_terminal_id);\n  IF auth.role()<>'service_role' THEN\n    SELECT * INTO v_me FROM public.app_users\n      WHERE auth_user_id=auth.uid() AND is_active=true LIMIT 1;\n    IF v_me.id IS NULL OR NOT (\n      v_me.role='admin' OR COALESCE((v_me.permissions->>'can_manage_sync_backup')::boolean,false)\n    ) THEN RAISE EXCEPTION 'SYNC_FORBIDDEN'; END IF;\n    IF NOT (v_me.role='admin' OR v_me.store_id IS NULL OR v_me.store_id=p_branch_id) THEN\n      RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN';\n    END IF;\n  END IF;\n  SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),\n         max(page.cursor)\n    INTO v_rows,v_cursor\n    FROM (\n      SELECT jsonb_build_object('id',x.id)::text cursor,x row_data\n      FROM public.issued_vouchers x\n      WHERE p_after_cursor IS NULL OR jsonb_build_object('id',x.id)::text>p_after_cursor\n      ORDER BY jsonb_build_object('id',x.id)::text\n      LIMIT LEAST(GREATEST(p_limit,10),2000)\n    ) page;\n  RETURN jsonb_build_object(\n    'rows',v_rows,\n    'cursor',CASE WHEN jsonb_array_length(v_rows)>=LEAST(GREATEST(p_limit,10),2000)\n                  THEN v_cursor ELSE NULL END\n  );\nEND $function$\n","volatility":"v","definition_md5":"2a0564a108930ffdaa326e3e9cf41de4","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"2a0564a108930ffdaa326e3e9cf41de4"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":1000,"owner":"postgres","config":["search_path=public, pg_temp"],"strict":false,"definer":true,"returns":"TABLE(table_name text, row_count bigint)","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"pos_sync_counts_scoped(text,text,text,integer)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_counts_scoped(p_organization_id text, p_branch_id text, p_terminal_id text, p_history_days integer DEFAULT 90)\n RETURNS TABLE(table_name text, row_count bigint)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE v_me public.app_users%ROWTYPE;\nBEGIN PERFORM public.pos_sync_validate_read_scope(p_organization_id,p_branch_id,p_terminal_id); IF auth.role()<>'service_role' THEN SELECT * INTO v_me FROM public.app_users WHERE auth_user_id=auth.uid() AND is_active=true LIMIT 1;\n IF v_me.id IS NULL OR NOT (v_me.role='admin' OR COALESCE((v_me.permissions->>'can_manage_sync_backup')::boolean,false)) THEN RAISE EXCEPTION 'SYNC_FORBIDDEN'; END IF;\n IF NOT (v_me.role='admin' OR v_me.store_id IS NULL OR v_me.store_id=p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; END IF;\n RETURN QUERY SELECT 'coupon_campaigns'::text table_name,count(*)::bigint row_count FROM public.\"coupon_campaigns\" x WHERE true UNION ALL SELECT 'shifts'::text table_name,count(*)::bigint row_count FROM public.\"shifts\" x WHERE x.store_id::text=p_branch_id UNION ALL SELECT 'issued_vouchers'::text table_name,count(*)::bigint row_count FROM public.\"issued_vouchers\" x WHERE x.store_id::text=p_branch_id UNION ALL SELECT 'activity_events'::text table_name,count(*)::bigint row_count FROM public.\"activity_events\" x WHERE x.store_id::text=p_branch_id UNION ALL SELECT 'app_users'::text table_name,count(*)::bigint row_count FROM public.\"app_users\" x WHERE x.store_id::text=p_branch_id UNION ALL SELECT 'audit_logs'::text table_name,count(*)::bigint row_count FROM public.\"audit_logs\" x WHERE x.store_id::text=p_branch_id AND (p_history_days>=7300 OR x.\"created_at\">=now()-make_interval(days=>GREATEST(p_history_days,30))) UNION ALL SELECT 'booking_payments'::text table_name,count(*)::bigint row_count FROM public.\"booking_payments\" x WHERE EXISTS(SELECT 1 FROM public.\"bookings\" p WHERE p.\"id\"::text=x.\"booking_id\"::text AND p.store_id::text=p_branch_id) UNION ALL SELECT 'bookings'::text table_name,count(*)::bigint row_count FROM public.\"bookings\" x WHERE x.store_id::text=p_branch_id UNION ALL SELECT 'branch_telemetry'::text table_name,count(*)::bigint row_count FROM public.\"branch_telemetry\" x WHERE x.store_id::text=p_branch_id UNION ALL SELECT 'cashiers'::text table_name,count(*)::bigint row_count FROM public.\"cashiers\" x WHERE x.store_id::text=p_branch_id UNION ALL SELECT 'coupon_events'::text table_name,count(*)::bigint row_count FROM public.\"co