at\">=now()-make_interval(days=>GREATEST(p_history_days,30))) UNION ALL SELECT 'entity_status_history'::text table_name,count(*)::bigint row_count FROM public.\"entity_status_history\" x WHERE x.store_id::text=p_branch_id UNION ALL SELECT 'nav_pins'::text table_name,count(*)::bigint row_count FROM public.\"nav_pins\" x WHERE true UNION ALL SELECT 'store_groups'::text table_name,count(*)::bigint row_count FROM public.\"store_groups\" x WHERE true;\nEND $function$\n","volatility":"v","definition_md5":"1172232dcd4a9487f529f565517fdcb3","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"0ffad730d36379c7b78000ae43c4ba5f","canonical_alternate_md5":["7777d68b1459cd5c562fbfc12f27de0d"]},{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":1000,"owner":"postgres","config":["search_path=public, pg_temp"],"strict":false,"definer":true,"returns":"TABLE(table_name text, row_count bigint)","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"pos_sync_counts(text,text,text,integer)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_counts(p_organization_id text, p_branch_id text, p_terminal_id text, p_history_days integer DEFAULT 90)\n RETURNS TABLE(table_name text, row_count bigint)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nBEGIN\n  RETURN QUERY\n    SELECT scoped.table_name,scoped.row_count\n    FROM public.pos_sync_counts_scoped(\n      p_organization_id,p_branch_id,p_terminal_id,p_history_days\n    ) scoped\n    WHERE scoped.table_name <> 'issued_vouchers'\n    UNION ALL\n    SELECT 'issued_vouchers'::text,count(*)::bigint FROM public.issued_vouchers\n    UNION ALL\n    SELECT 'change_history'::text,count(*)::bigint FROM public.change_history;\nEND $function$\n","volatility":"v","definition_md5":"a714eac72e00af9c7a562edeaa8bafa3","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"a714eac72e00a