ll(p_organization_id,p_branch_id,p_terminal_id,p_after_cursor,10) f;\n v_raw_count:=pg_catalog.jsonb_array_length(v_raw);\n IF v_raw_count>10 THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='POS_FEED_STREAM_INVALID_SOURCE'; END IF;\n -- Validate every raw cursor before emitting any prefix; never advance over\n -- malformed source data. JSONB retains exact signed bigint values.\n FOR v_row IN SELECT a.value FROM pg_catalog.jsonb_array_elements(v_raw) a(value) LOOP\n  v_cursor:=(v_row->>'cursor')::bigint;\n  IF v_cursor IS NULL OR v_cursor<=v_previous THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='POS_FEED_STREAM_INVALID_SOURCE'; END IF;\n  v_previous:=v_cursor;\n END LOOP;\n FOR v_row IN SELECT a.value FROM pg_catalog.jsonb_array_elements(v_raw) a(value) LOOP\n  v_projected:=public.pos_sync_history_project_v1(v_row,'',p_keep_commerce);\n  v_candidate:=v_rows||pg_catalog.jsonb_build_array(v_projected);\n  v_bytes:=pg_catalog.octet_length(v_candidate::text);\n  IF v_bytes>p_max_bytes AND v_count>0 THEN EXIT; END IF;\n  IF v_bytes>v_hard THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='POS_FEED_STREAM_ROW_TOO_LARGE'; END IF;\n  v_rows:=v_candidate; v_count:=v_count+1;\n  IF v_bytes>p_max_bytes THEN EXIT; END IF;\n END LOOP;\n v_bytes:=pg_catalog.octet_length(v_rows::text);\n v_more:=v_count<v_raw_count OR v_raw_count=10;\n PERFORM pg_catalog.set_config('response.headers',pg_catalog.jsonb_build_array(\n  pg_catalog.jsonb_build_object('X-POS-Feed-Projection','1'),\n  pg_catalog.jsonb_build_object('X-POS-Feed-Bytes',v_bytes::text),\n  pg_catalog.jsonb_build_object('X-POS-Feed-Rows',v_count::text),\n  pg_catalog.jsonb_build_object('X-POS-Feed-Continue',CASE WHEN v_more THEN '1' ELSE '0' END)\n )::text,true);\n RETURN v_rows;\nEND;\n$function$\n","volatility":"v","definition_md5":"f7c8221574a065caf04d4b16c1344d0f","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"f7c8221574a065caf04d4b16c1344d0f"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":0,"owner":"postgres","config":["search_path=pg_catalog, public"],"strict":false,"definer":false,"returns":"jsonb","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"pos_sync_history_index_v1(text,text,text,text,uuid,uuid,integer,boolean)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_history_index_v1(p_organization_id text, p_branch_id text, p_terminal_id text, p_action text, p_after_id uuid DEFAULT NULL::uuid, p_upper_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 1000, p_keep_commerce boolean DEFAULT false)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE\n v_upper uuid:=p_upper_id; v_ids jsonb:='[]'::jsonb; v_next uuid; v_more boolean:=false;\n v_count text; v_result jsonb;\nBEGIN\n PERFORM public.pos_sync_validate_read_scope(p_organization_id,p_branch_id,p_terminal_id);\n -- Runtime accepts only the same reviewed projection with LF/CRLF storage,\n -- and the captured-live/current-canonical immutable helper body forms.\n -- The migration's existing-source preflight below remains byte-exact.\n IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.pos_sync_history_project_v1(jsonb,text,boolean)')\n  AND md5(replace(p.prosrc,chr(13)||chr(10),chr(10)))='a5be97695f3e105ebde271e2f017ddee'\n  AND pg_get_userbyid(p.proowner)='postgres' AND p.prorettype='jsonb'::regtype AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')\n  AND NOT p.prosecdef AND p.proisstrict AND p.provolatile='i' AND p.proconfig=ARRAY['search_path=pg_catalog'])\n OR NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.change_history_immutable()')\n  AND replace(p.prosrc,chr(13)||chr(10),chr(10)) IN (chr(10)||'BEGIN RAISE EXCEPTION ''change_history is append-only''; END ',' BEGIN RAISE EXCEPTION ''change_history is append-only''; END ')\n  AND pg_get_userbyid(p.proowner)='postgres' AND p.prorettype='trigger'::regtype AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')\n  AND NOT p.prosecdef AND NOT p.proisstrict AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=public, pg_temp'])\n OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.change_history'::regclass AND tgname='change_history_no_change' AND tgenabled='O'\n  AND pg_get_triggerdef(oid)='CREATE TRIGGER change_history_no_change BEFORE DELETE OR UPDATE ON public.change_history FOR EACH ROW EXECUTE FUNCTION change_history_immutable()')\n THEN RAISE EXCEPTION 'HISTORY_INDEX_UNSUPPORTED_SOURCE'; END IF;\n IF p_action IS NULL OR p_action NOT IN ('begin','page','finish') OR p_limit IS NULL OR p_limit<1 OR p_limit>1000 OR p_keep_commerce IS NULL\n OR (p_action='begin' AND (p_after_id IS NOT NULL OR p_upper_id IS NOT NULL))\n OR (p_action='page' AND (p_upper_id IS NULL OR p_after_id>p_upper_id))\n OR (p_action='finish' AND p_after_id IS NOT NULL)\n THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='HISTORY_INDEX_INVALID_ARGUMENT'; END IF;\n IF p_action='begin' THEN SELECT h.id INTO v_upper FROM public.change_history h ORDER BY h.id DESC LIMIT 1; END IF;\n IF p_action='finish' THEN\n  SELECT count(*)::text INTO v_count FROM public.change_history h WHERE v_upper IS NOT NULL AND h.id<=v_upper;\n ELSE\n  WITH candidates AS MATERIALIZED (\n   SELECT h.id FROM public.change_history h WHERE v_upper IS NOT NULL AND h.id<=v_upper AND (p_after_id IS NULL OR h.id>p_after_id)\n   ORDER BY h.id LIMIT p_limit+1\n  ), selected AS (SELECT id FROM candidates ORDER BY id LIMIT p_limit)\n  SELECT COALESCE((SELECT jsonb_agg(id::text ORDER BY id) FROM selected),'[]'::jsonb),(SELECT count(*) FROM candidates)>p_limit\n   INTO v_ids,v_more;\n  IF v_more THEN v_next:=(v_ids->>-1)::uuid; END IF;\n END IF;\n v_result:=jsonb_build_object('protocol','history-index-v1','projection','history-project-v1:a5be97695f3e105ebde271e2f017ddee',\n  'organization_id',p_organization_id,'branch_id',p_branch_id,'terminal_id',p_terminal_id,'keep_commerce',p_keep_commerce,\n  'action',p_action,'upper_id',v_upper,'after_id',p_after_id,'ids',v_ids,'next_id',v_next,'complete',NOT v_more,'range_count',v_count);\n IF octet_length(v_result::text)>131072 THEN RAISE EXCEPTION 'HISTORY_INDEX_OVERSIZED'; END IF;\n PERFORM set_config('response.headers',jsonb_build_array(\n  jsonb_build_object('X-POS-History-Reconcile-Version','1'),jsonb_build_object('X-POS-History-Reconcile-Kind','index'),\n  jsonb_build_object('X-POS-History-Reconcile-Bytes',octet_length(v_result::text)::text),\n  jsonb_build_object('X-POS-History-Reconcile-Rows',jsonb_array_length(v_ids)::text))::text,true);\n RETURN v_result;\nEND;\n$function$\n","volatility":"v","definition_md5":"84af46c75f67966b58e8acea329f8dea","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"84af46c75f67966b58e8acea329f8dea"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":0,"owner":"postgres","config":["search_path=pg_catalog"],"strict":false,"definer":false,"returns":"jsonb","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"pos_sync_history_page_v1(text,text,text,text,integer,boolean,integer)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_history_page_v1(p_organization_id text, p_branch_id text, p_terminal_id text, p_after_cursor text DEFAULT NULL::text, p_history_days integer DEFAULT 90, p_keep_commerce boolean DEFAULT false, p_max_bytes integer DEFAULT 2097152)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n  v_raw jsonb;\n  v_rows jsonb := '[]'::jsonb;\n  v_row jsonb;\n  v_projected jsonb;\n  v_envelope jsonb;\n  v_candidate jsonb;\n  v_cursor text;\n  v_last_id uuid;\n  v_count integer := 0;\n  v_total integer;\n  v_bytes integer;\n  v_hard constant integer := 5242880;\nBEGIN\n  -- Check before delegation: a minimum-100 legacy source must never allocate\n  -- its raw page here. Any future source change requires explicit review.\n  IF NOT true\n     OR pg_catalog.md5(pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure('public.pos_sync_bootstrap(text,text,text,text,text,integer,integer)'))) IS DISTINCT FROM '2a0564a108930ffdaa326e3e9cf41de4'\n     OR pg_catalog.md5(pg_catalog.pg_get_functiondef(pg_catalog.to_regprocedure('public.pos_sync_bootstrap_scoped(text,text,text,text,text,integer,integer)'))) IS DISTINCT FROM 'b4306345e37e638c610e8484a479c510' THEN\n    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='POS_HISTORY_STREAM_UNSUPPORTED_SOURCE';\n  END IF;\n  IF p_max_bytes IS NULL OR p_max_bytes < 1024 OR p_max_bytes > 2097152 OR p_keep_commerce IS NULL THEN\n    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='POS_HISTORY_STREAM_INVALID_ARGUMENT';\n  END IF;\n  v_raw := public.pos_sync_bootstrap(p_organization_id,p_branch_id,p_terminal_id,'change_history',p_after_cursor,p_history_days,10);\n  IF pg_catalog.jsonb_typeof(v_raw->'rows') IS DISTINCT FROM 'array' THEN\n    RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='POS_HISTORY_STREAM_INVALID_SOURCE';\n  END IF;\n  v_total := pg_catalog.jsonb_array_length(v_raw->'rows');\n  IF v_total > 10 THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='POS_HISTORY_STREAM_INVALID_SOURCE'; END IF;\n  FOR v_row IN SELECT a.value FROM pg_catalog.jsonb_array_elements(v_raw->'rows') AS a(value) LOOP\n    v_last_id := (v_row->>'id')::uuid;\n    IF v_last_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0001',MESSAGE='POS_HISTORY_STREAM_INVALID_SOURCE'; END IF;\n    v_projected := public.pos_sync_history_project_v1(v_row,'change_history',p_keep_commerce);\n    v_cursor := CASE WHEN v_count+1=v_total THEN v_raw->>'cursor' ELSE pg_catalog.jsonb_build_object('id',v_last_id)::text END;\n    v_candidate := pg_catalog.jsonb_build_object('rows',v_rows||pg_catalog.jsonb_build_array(v_projected),'cursor',v_cursor);\n    v_bytes := pg_catalog.octet_length(v_candidate::text);\n    IF v_bytes > p_max_bytes AND v_count > 0 THEN EXIT; END IF;\n    IF v_bytes > v_hard THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='POS_HISTORY_STREAM_ROW_TOO_LARGE'; END IF;\n    v_rows := v_rows||pg_catalog.jsonb_build_array(v_projected);\n    v_count := v_count+1;\n    v_envelope := v_candidate;\n    IF v_bytes > p_max_bytes THEN EXIT; END IF;\n  END LOOP;\n  IF v_count=0 THEN v_envelope := pg_catalog.jsonb_build_object('rows','[]'::jsonb,'cursor',v_raw->>'cursor'); END IF;\n  -- A prefix cut must resume from the last KEPT raw UUID, never the lookahead.\n  IF v_count < v_total THEN\n    v_envelope := pg_catalog.jsonb_set(v_envelope,ARRAY['cursor'],pg_catalog.to_jsonb(pg_catalog.jsonb_build_object('id',v_rows->(v_count-1)->>'id')::text));\n  END IF;\n  v_bytes := pg_catalog.octet_length(v_envelope::text);\n  IF v_bytes > v_hard THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='POS_HISTORY_STREAM_ROW_TOO_LARGE'; END IF;\n  PERFORM pg_catalog.set_config('response.headers',pg_catalog.jsonb_build_array(\n    pg_catalog.jsonb_build_object('X-POS-History-Projection','1'),\n    pg_catalog.jsonb_build_object('X-POS-History-Bytes',v_bytes::text),\n    pg_catalog.jsonb_build_object('X-POS-History-Rows',v_count::text)\n  )::text,true);\n  RETURN v_envelope;\nEND;\n$function$\n","volatility":"v","definition_md5":"ff88a5b82bba6bf10fe122ec5cca7083","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"ff88a5b82bba6bf10fe122ec5cca7083"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":0,"owner":"postgres","config":["search_path=pg_catalog"],"strict":true,"definer":false,"returns":"jsonb","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"pos_sync_history_project_v1(jsonb,text,boolean)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_history_project_v1(p_value jsonb, p_table text DEFAULT ''::text, p_keep_commerce boolean DEFAULT false)\n RETURNS jsonb\n LANGUAGE plpgsql\n IMMUTABLE STRICT\n SET search_path TO 'pg_catalog'\nAS $function$\nDECLARE\n  v_row jsonb := p_value;\n  v_context text := p_table;\n  v_result jsonb := '{}'::jsonb;\n  v_price jsonb;\n  v_remove text[];\n  v_number double precision;\nBEGIN\n  -- The former Worker parsed JSON numbers before serializing the response.\n  -- JSON.stringify maps non-finite JavaScript numbers to null. Preserve that\n  -- transport behavior for valid PostgreSQL numeric values beyond float8.\n  IF pg_catalog.jsonb_typeof(p_value) = 'number' AND pg_catalog.abs((p_value::text)::numeric) > 1 THEN\n    BEGIN\n      v_number := (p_value::text)::double precision;\n    EXCEPTION WHEN numeric_value_out_of_range THEN RETURN 'null'::jsonb;\n    END;\n  END IF;\n  IF pg_catalog.jsonb_typeof(p_value) = 'array' THEN\n    IF NOT pg_catalog.jsonb_path_exists(p_value,'strict $[*] ? (@.type() == \"object\" || @.type() == \"array\" || (@.type() == \"number\" && (@ > 1e308 || @ < -1e308)))') THEN\n      RETURN p_value;\n    END IF;\n    SELECT COALESCE(pg_catalog.jsonb_agg(CASE pg_catalog.jsonb_typeof(a.value)\n      WHEN 'object' THEN public.pos_sync_history_project_v1(a.value,p_table,p_keep_commerce)\n      WHEN 'array' THEN public.pos_sync_history_project_v1(a.value,p_table,p_keep_commerce)\n      WHEN 'number' THEN CASE WHEN a.value>'1e308'::jsonb OR a.value<'-1e308'::jsonb\n        THEN public.pos_sync_history_project_v1(a.value,p_table,p_keep_commerce) ELSE a.value END\n      ELSE a.value END ORDER BY a.ordinality),'[]'::jsonb)\n      INTO v_result FROM pg_catalog.jsonb_array_elements(p_value) WITH ORDINALITY AS a(value,ordinality);\n    RETURN v_result;\n  END IF;\n  IF pg_catalog.jsonb_typeof(p_value) <> 'object' THEN RETURN p_value; END IF;\n  IF NOT p_keep_commerce\n     AND (p_table = 'settings_scoped' OR v_row->>'table_name' = 'settings_scoped')\n     AND pg_catalog.jsonb_typeof(v_row->'key') = 'string'\n     AND pg_catalog.left(v_row->>'key',14) = 'product_price:'\n     AND pg_catalog.jsonb_typeof(v_row->'value') IN ('object','array') THEN\n    IF pg_catalog.jsonb_typeof(v_row->'value') = 'array' THEN\n      SELECT COALESCE(pg_catalog.jsonb_object_agg((a.ordinality-1)::text,a.value),'{}'::jsonb)\n        INTO v_price FROM pg_catalog.jsonb_array_elements(v_row->'value') WITH ORDINALITY AS a(value,ordinality);\n    ELSE v_price := (v_row->'value') - 'ecom_price'; END IF;\n    v_row := pg_catalog.jsonb_set(v_row,ARRAY['value'],v_price,false);\n  END IF;\n  IF pg_catalog.jsonb_typeof(v_row->'table_name') = 'string' THEN v_context := v_row->>'table_name'; END IF;\n  v_remove:=CASE WHEN v_context='terminal_tokens' THEN ARRAY['claim_secret_hash','claim_proof','claimed_proof_hash']::text[] ELSE ARRAY[]::text[] END;\n  IF NOT p_keep_commerce THEN\n    v_remove:=v_remove||ARRAY['ecommerceEnabled']::text[];\n    IF v_context='products' THEN v_remove:=v_remove||ARRAY['ecom_price','ecom_visible','ecom_enabled','is_published']::text[]; END IF;\n  END IF;\n  -- Reuse untouched maps, including their large enclosing images. Materialize\n  -- projections once and aggregate only changed children, never every key.\n  IF pg_catalog.jsonb_path_exists(v_row,'strict $.* ? (@.type() == \"object\" || @.type() == \"array\" || (@.type() == \"number\" && (@ > 1e308 || @ < -1e308)))') THEN\n    WITH children AS MATERIALIZED (\n      SELECT e.key,e.value FROM pg_catalog.jsonb_each(v_row) AS e\n      WHERE NOT(e.key=ANY(v_remove)) AND CASE pg_catalog.jsonb_typeof(e.value)\n        WHEN 'object' THEN true WHEN 'array' THEN true\n        WHEN 'number' THEN e.value>'1e308'::jsonb OR e.value<'-1e308'::jsonb ELSE false END\n    ), projected AS MATERIALIZED (\n      SELECT key,value,public.pos_sync_history_project_v1(value,v_context,p_keep_commerce) AS next_value FROM children\n    ) SELECT pg_catalog.jsonb_object_agg(key,next_value) INTO v_result FROM projected WHERE next_value IS DISTINCT FROM value;\n    IF v_result IS NOT NULL THEN v_row:=v_row||v_result; END IF;\n  END IF;\n  IF NOT v_row ?| v_remove THEN RETURN v_row; END IF;\n  v_result:=v_row-v_remove;\n  RETURN v_result;\nEND;\n$function$\n","volatility":"i","definition_md5":"4633e04e150c350518938f2ba661fca1","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"4633e04e150c350518938f2ba661fca1"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":0,"owner":"postgres","config":["search_path=pg_catalog, public"],"strict":false,"definer":false,"returns":"jsonb","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"pos_sync_history_rows_v1(text,text,text,jsonb,boolean,integer)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_history_rows_v1(p_organization_id text, p_branch_id text, p_terminal_id text, p_ids jsonb, p_keep_commerce boolean DEFAULT false, p_max_bytes integer DEFAULT 2097152)\n RETURNS jsonb\n LANGUAGE plpgsql\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE\n v_id text; v_raw public.change_history%ROWTYPE; v_projected jsonb; v_wire jsonb;\n v_rows jsonb:='[]'::jsonb; v_candidate jsonb; v_result jsonb; v_remaining jsonb; v_count integer:=0; v_bytes integer;\nBEGIN\n PERFORM public.pos_sync_validate_read_scope(p_organization_id,p_branch_id,p_terminal_id);\n IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.pos_sync_history_project_v1(jsonb,text,boolean)')\n  AND md5(replace(p.prosrc,chr(13)||chr(10),chr(10)))='a5be97695f3e105ebde271e2f017ddee'\n  AND pg_get_userbyid(p.proowner)='postgres' AND p.prorettype='jsonb'::regtype AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')\n  AND NOT p.prosecdef AND p.proisstrict AND p.provolatile='i' AND p.proconfig=ARRAY['search_path=pg_catalog'])\n OR NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('public.change_history_immutable()')\n  AND replace(p.prosrc,chr(13)||chr(10),chr(10)) IN (chr(10)||'BEGIN RAISE EXCEPTION ''change_history is append-only''; END ',' BEGIN RAISE EXCEPTION ''change_history is append-only''; END ')\n  AND pg_get_userbyid(p.proowner)='postgres' AND p.prorettype='trigger'::regtype AND p.prolang=(SELECT oid FROM pg_language WHERE lanname='plpgsql')\n  AND NOT p.prosecdef AND NOT p.proisstrict AND p.provolatile='v' AND p.proconfig=ARRAY['search_path=public, pg_temp'])\n OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.change_history'::regclass AND tgname='change_history_no_change' AND tgenabled='O'\n  AND pg_get_triggerdef(oid)='CREATE TRIGGER change_history_no_change BEFORE DELETE OR UPDATE ON public.change_history FOR EACH ROW EXECUTE FUNCTION change_history_immutable()')\n THEN RAISE EXCEPTION 'HISTORY_INDEX_UNSUPPORTED_SOURCE'; END IF;\n IF p_ids IS NULL OR jsonb_typeof(p_ids)<>'array' OR jsonb_array_length(p_ids)<1 OR jsonb_array_length(p_ids)>10\n OR p_keep_commerce IS NULL OR p_max_bytes IS NULL OR p_max_bytes<1024 OR p_max_bytes>2097152\n THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='HISTORY_ROWS_INVALID_ARGUMENT'; END IF;\n IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_ids) x(value) WHERE jsonb_typeof(value)<>'string'\n   OR (value#>>'{}')!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')\n OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(p_ids))<>jsonb_array_length(p_ids)\n THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='HISTORY_ROWS_INVALID_IDS'; END IF;\n FOR v_id IN SELECT value FROM jsonb_array_elements_text(p_ids) LOOP\n  SELECT * INTO v_raw FROM public.change_history WHERE id=v_id::uuid;\n  IF NOT FOUND THEN RAISE EXCEPTION 'HISTORY_INDEX_ROW_MISSING'; END IF;\n  IF NOT isfinite(v_raw.server_timestamp) OR v_raw.server_timestamp<'0001-01-01T00:00:00Z'::timestamptz\n   OR v_raw.server_timestamp>'9999-12-31T23:59:59.999999Z'::timestamptz\n   THEN RAISE EXCEPTION 'HISTORY_ROWS_TIMESTAMP_UNSUPPORTED'; END IF;\n  v_projected:=public.pos_sync_history_project_v1(to_jsonb(v_raw),'change_history',p_keep_commerce);\n  v_wire:=(v_projected-'old_value'-'new_value'-'revision'-'server_timestamp')||jsonb_build_object(\n   'old_value_json',CASE WHEN v_projected->'old_value'='null'::jsonb THEN NULL ELSE (v_projected->'old_value')::text END,\n   'new_value_json',CASE WHEN v_projected->'new_value'='null'::jsonb THEN NULL ELSE (v_projected->'new_value')::text END,\n   'revision',v_raw.revision::text,\n   'server_timestamp',to_char(v_raw.server_timestamp AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US')||'0Z');\n  SELECT COALESCE(jsonb_agg(value ORDER BY ordinality),'[]'::jsonb) INTO v_remaining\n   FROM jsonb_array_elements(p_ids) WITH ORDINALITY x(value,ordinality) WHERE ordinality>v_count+1;\n  v_candidate:=jsonb_build_object('protocol','history-rows-v1','projection','history-project-v1:a5be97695f3e105ebde271e2f017ddee',\n   'organization_id',p_organization_id,'branch_id',p_branch_id,'terminal_id',p_terminal_id,'keep_commerce',p_keep_commerce,\n   'requested_ids',p_ids,'rows',v_rows||jsonb_build_array(v_wire),'remaining_ids',v_remaining);\n  v_bytes:=octet_length(v_candidate::text);\n  IF v_bytes>p_max_bytes AND v_count>0 THEN EXIT; END IF;\n  IF v_bytes>5242880 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='HISTORY_ROWS_SINGLE_ROW_TOO_LARGE'; END IF;\n  v_result:=v_candidate;v_rows:=v_rows||jsonb_build_array(v_wire);v_count:=v_count+1;\n  IF v_bytes>p_max_bytes THEN EXIT; END IF;\n END LOOP;\n IF v_result IS NULL THEN RAISE EXCEPTION 'HISTORY_ROWS_EMPTY'; END IF;\n PERFORM set_config('response.headers',jsonb_build_array(\n  jsonb_build_object('X-POS-History-Reconcile-Version','1'),\n  jsonb_build_object('X-POS-History-Reconcile-Kind','rows'),\n  jsonb_build_object('X-POS-History-Reconcile-Bytes',octet_length(v_result::text)::text),\n  jsonb_build_object('X-POS-History-Reconcile-Rows',v_count::text))::text,true);\n RETURN v_result;\nEND;\n$function$\n","volatility":"v","definition_md5":"6e502cf4dba93421eaced42b13e055c6","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"6e502cf4dba93421eaced42b13e055c6"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":1000,"owner":"postgres","config":["search_path=public, pg_temp"],"strict":false,"definer":true,"returns":"TABLE(cursor bigint, table_name text, entity_id text, operation text, row_version bigint, tombstone boolean, row_data jsonb)","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"pos_sync_pull(text,text,text,bigint,integer)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_pull(p_organization_id text, p_branch_id text, p_terminal_id text, p_after_cursor bigint DEFAULT 0, p_limit integer DEFAULT 500)\n RETURNS TABLE(cursor bigint, table_name text, entity_id text, operation text, row_version bigint, tombstone boolean, row_data jsonb)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE v_me public.app_users%ROWTYPE;\nBEGIN PERFORM public.pos_sync_validate_read_scope(p_organization_id,p_branch_id,p_terminal_id); IF auth.role()<>'service_role' THEN SELECT * INTO v_me FROM public.app_users WHERE auth_user_id=auth.uid() AND is_active=true LIMIT 1;\n IF v_me.id IS NULL OR NOT (v_me.role='admin' OR COALESCE((v_me.permissions->>'can_manage_sync_backup')::boolean,false)) THEN RAISE EXCEPTION 'SYNC_FORBIDDEN'; END IF;\n IF NOT (v_me.role='admin' OR v_me.store_id IS NULL OR v_me.store_id=p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; END IF;\n -- cluster-catalogue-read-filter\n RETURN QUERY WITH feed_page AS MATERIALIZED (\n  SELECT candidate.cursor,candidate.table_name,candidate.entity_id,candidate.operation,candidate.row_version,candidate.tombstone\n  FROM (SELECT DISTINCT unnest(ARRAY[p_branch_id,'global']) AS branch_id) scopes\n  CROSS JOIN LATERAL (\n   (SELECT c.cursor,c.table_name,c.entity_id,c.operation,c.row_version,c.tombstone\n    FROM public.sync_change_feed c\n    WHERE c.organization_id=p_organization_id AND c.branch_id=scopes.branch_id\n      AND c.terminal_id IS NULL AND c.cursor>p_after_cursor\n    ORDER BY c.cursor LIMIT LEAST(GREATEST(p_limit,10),2000))\n   UNION ALL\n   (SELECT c.cursor,c.table_name,c.entity_id,c.operation,c.row_version,c.tombstone\n    FROM public.sync_change_feed c\n    WHERE c.organization_id=p_organization_id AND c.branch_id=scopes.branch_id\n      AND c.terminal_id=p_terminal_id AND c.terminal_id IS NOT NULL AND c.cursor>p_after_cursor\n    ORDER BY c.cursor LIMIT LEAST(GREATEST(p_limit,10),2000))\n  ) candidate\n  ORDER BY candidate.cursor LIMIT LEAST(GREATEST(p_limit,10),2000)\n )\n SELECT f.cursor,f.table_name,f.entity_id,f.operation,f.row_version,f.tombstone,CASE f.table_name WHEN 'coupon_campaigns' THEN (SELECT to_jsonb(x) FROM public.\"coupon_campaigns\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'shifts' THEN (SELECT to_jsonb(x) FROM public.\"shifts\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'issued_vouchers' THEN (SELECT to_jsonb(x) FROM public.\"issued_vouchers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'activity_events' THEN (SELECT to_jsonb(x) FROM public.\"activity_events\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'app_users' THEN (SELECT to_jsonb(x) FROM public.\"app_users\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'audit_logs' THEN (SELECT to_jsonb(x) FROM public.\"audit_logs\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'booking_payments' THEN (SELECT to_jsonb(x) FROM public.\"booking_payments\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'bookings' THEN (SELECT to_jsonb(x) FROM public.\"bookings\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'branch_telemetry' THEN (SELECT to_jsonb(x) FROM public.\"branch_telemetry\" x WHERE x.\"terminal_id\"=((f.entity_id::jsonb)->>'terminal_id') LIMIT 1)\n    WHEN 'cashiers' THEN (SELECT to_jsonb(x) FROM public.\"cashiers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'coupon_events' THEN (SELECT to_jsonb(x) FROM public.\"coupon_events\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'drawer_events' THEN (SELECT to_jsonb(x) FROM public.\"drawer_events\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'held_orders' THEN (SELECT to_jsonb(x) FROM public.\"held_orders\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id') LIMIT 1)\n    WHEN 'integration_settings' THEN (SELECT to_jsonb(x) FROM public.\"integration_settings\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'item_activity_logs' THEN (SELECT to_jsonb(x) FROM public.\"item_activity_logs\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'member_verifications' THEN (SELECT to_jsonb(x) FROM public.\"member_verifications\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'members' THEN (SELECT to_jsonb(x) - ARRAY['auth_user_id']::text[] FROM public.\"members\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'membership_tiers' THEN (SELECT to_jsonb(x) FROM public.\"membership_tiers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'offline_sync_audit_log' THEN (SELECT to_jsonb(x) FROM public.\"offline_sync_audit_log\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'payment_transactions' THEN (SELECT to_jsonb(x) FROM public.\"payment_transactions\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'payment_types' THEN (SELECT to_jsonb(x) FROM public.\"payment_types\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'pin_attempts' THEN (SELECT to_jsonb(x) FROM public.\"pin_attempts\" x WHERE x.\"key\"=((f.entity_id::jsonb)->>'key') LIMIT 1)\n    WHEN 'pos_settings' THEN (SELECT to_jsonb(x) FROM public.\"pos_settings\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::integer LIMIT 1)\n    WHEN 'product_barcodes' THEN (SELECT to_jsonb(x) FROM public.\"product_barcodes\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid AND public.product_available_in_catalogue(x.product_id,p_branch_id) LIMIT 1)\n    WHEN 'product_categories' THEN (SELECT to_jsonb(x) FROM public.\"product_categories\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'products' THEN (SELECT to_jsonb(x) FROM public.\"products\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid AND public.product_available_in_catalogue(x.id,p_branch_id) LIMIT 1)\n    WHEN 'promotions' THEN (SELECT to_jsonb(x) FROM public.\"promotions\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid AND (x.foc_product_id IS NULL OR public.product_available_in_catalogue(x.foc_product_id,p_branch_id)) LIMIT 1)\n    WHEN 'public_flags' THEN (SELECT to_jsonb(x) FROM public.\"public_flags\" x WHERE x.\"key\"=((f.entity_id::jsonb)->>'key') LIMIT 1)\n    WHEN 'purchase_order_items' THEN (SELECT to_jsonb(x) FROM public.\"purchase_order_items\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'purchase_orders' THEN (SELECT to_jsonb(x) FROM public.\"purchase_orders\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'sale_items' THEN (SELECT to_jsonb(x) FROM public.\"sale_items\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'sales' THEN (SELECT to_jsonb(x) FROM public.\"sales\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'secure_settings' THEN (SELECT to_jsonb(x) FROM public.\"secure_settings\" x WHERE x.\"key\"=((f.entity_id::jsonb)->>'key') LIMIT 1)\n    WHEN 'security_findings' THEN (SELECT to_jsonb(x) FROM public.\"security_findings\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'settings_locks' THEN (SELECT to_jsonb(x) FROM public.\"settings_locks\" x WHERE x.\"section\"=((f.entity_id::jsonb)->>'section') LIMIT 1)\n    WHEN 'settings_overrides' THEN (SELECT to_jsonb(x) FROM public.\"settings_overrides\" x WHERE x.\"scope\"=((f.entity_id::jsonb)->>'scope') AND x.\"scope_id\"=((f.entity_id::jsonb)->>'scope_id') AND x.\"section\"=((f.entity_id::jsonb)->>'section') LIMIT 1)\n    WHEN 'shift_sessions' THEN (SELECT to_jsonb(x) FROM public.\"shift_sessions\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'sku_audit' THEN (SELECT to_jsonb(x) FROM public.\"sku_audit\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'staff_roles' THEN (SELECT to_jsonb(x) FROM public.\"staff_roles\" x WHERE x.\"slug\"=((f.entity_id::jsonb)->>'slug') LIMIT 1)\n    WHEN 'stock_adjustments' THEN (SELECT to_jsonb(x) FROM public.\"stock_adjustments\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'stock_delta_applied' THEN (SELECT to_jsonb(x) FROM public.\"stock_delta_applied\" x WHERE x.\"movement_id\"=((f.entity_id::jsonb)->>'movement_id')::uuid LIMIT 1)\n    WHEN 'stock_transfer_items' THEN (SELECT to_jsonb(x) FROM public.\"stock_transfer_items\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'stock_transfers' THEN (SELECT to_jsonb(x) FROM public.\"stock_transfers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'stores' THEN (SELECT to_jsonb(x) FROM public.\"stores\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id') LIMIT 1)\n    WHEN 'suppliers' THEN (SELECT to_jsonb(x) FROM public.\"suppliers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'sync_metadata' THEN (SELECT to_jsonb(x) FROM public.\"sync_metadata\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'system_audit_logs' THEN (SELECT to_jsonb(x) FROM public.\"system_audit_logs\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'terminal_commands' THEN (SELECT to_jsonb(x) FROM public.\"terminal_commands\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'terminal_tokens' THEN (SELECT to_jsonb(x) FROM public.\"terminal_tokens\" x WHERE x.\"