b_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'authorization_actions' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"authorization_actions\" x WHERE ((lower(x.scope_type)='global' OR (lower(x.scope_type)='branch' AND x.scope_id::text=p_branch_id) OR (lower(x.scope_type)='cluster' AND EXISTS(SELECT 1 FROM public.stores scoped_store WHERE scoped_store.id::text=p_branch_id AND COALESCE(NULLIF(scoped_store.group_id,''),'default')=x.scope_id::text))))  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'authorization_action_history' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"authorization_action_history\" x WHERE ((lower(x.scope_type)='global' OR (lower(x.scope_type)='branch' AND x.scope_id::text=p_branch_id) OR (lower(x.scope_type)='cluster' AND EXISTS(SELECT 1 FROM public.stores scoped_store WHERE scoped_store.id::text=p_branch_id AND COALESCE(NULLIF(scoped_store.group_id,''),'default')=x.scope_id::text))))  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'authorization_requests' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"authorization_requests\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'authorization_log' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"authorization_log\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'record_edits' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"record_edits\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'shift_cash_counts' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"shift_cash_counts\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'shift_close_events' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"shift_close_events\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'shift_reconciliations' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"shift_reconciliations\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'shift_variance_alerts' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"shift_variance_alerts\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'shift_notifications' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"shift_notifications\" x WHERE (x.store_id::text=p_branch_id) AND (p_history_days>=7300 OR x.\"created_at\">=now()-make_interval(days=>GREATEST(p_history_days,30))) AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'entity_status_history' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"entity_status_history\" x WHERE (x.store_id::text=p_branch_id)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'nav_pins' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"nav_pins\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'store_groups' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"store_groups\" x WHERE (true)  AND (p_after_cursor IS NULL OR jsonb_build_object('id',x.\"id\")::text>p_after_cursor) ORDER BY jsonb_build_object('id',x.\"id\")::text LIMIT LEAST(GREATEST(p_limit,10),2000)) page;\n    WHEN 'change_history' THEN SELECT COALESCE(jsonb_agg(to_jsonb(page.row_data) ORDER BY page.cursor),'[]'::jsonb),max(page.cursor) INTO v_rows,v_cursor FROM (SELECT jsonb_build_object('id',x.\"id\")::text cursor,x row_data FROM public.\"change_history\" x WHERE (public.pos_sync_history_row_visible_v1(v_history_company,p_organization_id,p_branch_id,x.organization_id,x.scope_type,x.scope_id))  AND (p_after_cursor IS NULL OR x.\"id\">((p_after_cursor::jsonb)->>'id')::uuid) ORDER BY x.\"id\" LIMIT LEAST(GREATEST(p_limit,10),2000)) page; ELSE RAISE EXCEPTION 'SYNC_TABLE_FORBIDDEN'; END CASE;\n RETURN jsonb_build_object('rows',v_rows,'cursor',CASE WHEN jsonb_array_length(v_rows)>=LEAST(GREATEST(p_limit,10),2000) THEN v_cursor ELSE NULL END);\nEND $function$\n","volatility":"v","definition_md5":"de04be7ea94c19c531212289907dc789","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"b4306345e37e638c610e8484a479c510","old_md5":"b4306345e37e638c610e8484a479c510"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":1000,"owner":"postgres","config":["search_path=public, pg_temp"],"strict":false,"definer":true,"returns":"TABLE(table_name text, row_count bigint)","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"pos_sync_counts(text,text,text,integer)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_counts(p_organization_id text, p_branch_id text, p_terminal_id text, p_history_days integer DEFAULT 90)\n RETURNS TABLE(table_name text, row_count bigint)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE v_history_company boolean;\nBEGIN\n v_history_company := public.pos_sync_history_company_scope_v1(p_organization_id,p_branch_id,p_terminal_id);\n  RETURN QUERY\n    SELECT scoped.table_name,scoped.row_count\n    FROM public.pos_sync_counts_scoped(\n      p_organization_id,p_branch_id,p_terminal_id,p_history_days\n    ) scoped\n    WHERE scoped.table_name NOT IN ('issued_vouchers','change_history')\n    UNION ALL\n    SELECT 'issued_vouchers'::text,count(*)::bigint FROM public.issued_vouchers\n    UNION ALL\n    SELECT 'change_history'::text,count(*)::bigint FROM public.change_history h WHERE public.pos_sync_history_row_visible_v1(v_history_company,p_organization_id,p_branch_id,h.organization_id,h.scope_type,h.scope_id);\nEND $function$\n","volatility":"v","definition_md5":"51b5528a610d990b189f389ed0be2fa1","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"a714eac72e00af9c7a562edeaa8bafa3","canonical_alternate_md5":["0b30a999e8aec9f544e67e1db25eed40"],"old_md5":"a714eac72e00af9c7a562edeaa8bafa3"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","cost":100,"rows":1000,"owner":"postgres","config":["search_path=public, pg_temp"],"strict":false,"definer":true,"returns":"TABLE(cursor bigint, table_name text, entity_id text, operation text, row_version bigint, tombstone boolean, row_data jsonb)","support":"-","language":"plpgsql","parallel":"u","leakproof":false,"signature":"pos_sync_pull(text,text,text,bigint,integer)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_pull(p_organization_id text, p_branch_id text, p_terminal_id text, p_after_cursor bigint DEFAULT 0, p_limit integer DEFAULT 500)\n RETURNS TABLE(cursor bigint, table_name text, entity_id text, operation text, row_version bigint, tombstone boolean, row_data jsonb)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public', 'pg_temp'\nAS $function$\nDECLARE\n v_history_company boolean; v_me public.app_users%ROWTYPE;\nBEGIN v_history_company := public.pos_sync_history_company_scope_v1(p_organization_id,p_branch_id,p_terminal_id); IF auth.role()<>'service_role' THEN SELECT * INTO v_me FROM public.app_users WHERE auth_user_id=auth.uid() AND is_active=true LIMIT 1;\n IF v_me.id IS NULL OR NOT (v_me.role='admin' OR COALESCE((v_me.permissions->>'can_manage_sync_backup')::boolean,false)) THEN RAISE EXCEPTION 'SYNC_FORBIDDEN'; END IF;\n IF NOT (v_me.role='admin' OR v_me.store_id IS NULL OR v_me.store_id=p_branch_id) THEN RAISE EXCEPTION 'SYNC_BRANCH_FORBIDDEN'; END IF; END IF;\n -- cluster-catalogue-read-filter\n RETURN QUERY WITH feed_page AS MATERIALIZED (\n  SELECT candidate.cursor,candidate.table_name,candidate.entity_id,candidate.operation,candidate.row_version,candidate.tombstone\n  FROM (SELECT DISTINCT unnest(ARRAY[p_branch_id,'global']) AS branch_id) scopes\n  CROSS JOIN LATERAL (\n   (SELECT c.cursor,c.table_name,c.entity_id,c.operation,c.row_version,c.tombstone\n    FROM public.sync_change_feed c\n    WHERE c.organization_id=p_organization_id AND c.branch_id=scopes.branch_id\n      AND c.terminal_id IS NULL AND c.cursor>p_after_cursor AND (c.table_name<>'change_history' OR (NOT c.tombstone AND EXISTS(SELECT 1 FROM public.change_history history_scope_row WHERE history_scope_row.id=((c.entity_id::jsonb)->>'id')::uuid AND public.pos_sync_history_row_visible_v1(v_history_company,p_organization_id,p_branch_id,history_scope_row.organization_id,history_scope_row.scope_type,history_scope_row.scope_id))))\n    ORDER BY c.cursor LIMIT LEAST(GREATEST(p_limit,10),2000))\n   UNION ALL\n   (SELECT c.cursor,c.table_name,c.entity_id,c.operation,c.row_version,c.tombstone\n    FROM public.sync_change_feed c\n    WHERE c.organization_id=p_organization_id AND c.branch_id=scopes.branch_id\n      AND c.terminal_id=p_terminal_id AND c.terminal_id IS NOT NULL AND c.cursor>p_after_cursor AND (c.table_name<>'change_history' OR (NOT c.tombstone AND EXISTS(SELECT 1 FROM public.change_history history_scope_row WHERE history_scope_row.id=((c.entity_id::jsonb)->>'id')::uuid AND public.pos_sync_history_row_visible_v1(v_history_company,p_organization_id,p_branch_id,history_scope_row.organization_id,history_scope_row.scope_type,history_scope_row.scope_id))))\n    ORDER BY c.cursor LIMIT LEAST(GREATEST(p_limit,10),2000))\n  ) candidate\n  ORDER BY candidate.cursor LIMIT LEAST(GREATEST(p_limit,10),2000)\n )\n SELECT f.cursor,f.table_name,f.entity_id,f.operation,f.row_version,f.tombstone,CASE f.table_name WHEN 'coupon_campaigns' THEN (SELECT to_jsonb(x) FROM public.\"coupon_campaigns\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'shifts' THEN (SELECT to_jsonb(x) FROM public.\"shifts\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'issued_vouchers' THEN (SELECT to_jsonb(x) FROM public.\"issued_vouchers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'activity_events' THEN (SELECT to_jsonb(x) FROM public.\"activity_events\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'app_users' THEN (SELECT to_jsonb(x) FROM public.\"app_users\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'audit_logs' THEN (SELECT to_jsonb(x) FROM public.\"audit_logs\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'booking_payments' THEN (SELECT to_jsonb(x) FROM public.\"booking_payments\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'bookings' THEN (SELECT to_jsonb(x) FROM public.\"bookings\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'branch_telemetry' THEN (SELECT to_jsonb(x) FROM public.\"branch_telemetry\" x WHERE x.\"terminal_id\"=((f.entity_id::jsonb)->>'terminal_id') LIMIT 1)\n    WHEN 'cashiers' THEN (SELECT to_jsonb(x) FROM public.\"cashiers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'coupon_events' THEN (SELECT to_jsonb(x) FROM public.\"coupon_events\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'drawer_events' THEN (SELECT to_jsonb(x) FROM public.\"drawer_events\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'held_orders' THEN (SELECT to_jsonb(x) FROM public.\"held_orders\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id') LIMIT 1)\n    WHEN 'integration_settings' THEN (SELECT to_jsonb(x) FROM public.\"integration_settings\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'item_activity_logs' THEN (SELECT to_jsonb(x) FROM public.\"item_activity_logs\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'member_verifications' THEN (SELECT to_jsonb(x) FROM public.\"member_verifications\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'members' THEN (SELECT to_jsonb(x) - ARRAY['auth_user_id']::text[] FROM public.\"members\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'membership_tiers' THEN (SELECT to_jsonb(x) FROM public.\"membership_tiers\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'offline_sync_audit_log' THEN (SELECT to_jsonb(x) FROM public.\"offline_sync_audit_log\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'payment_transactions' THEN (SELECT to_jsonb(x) FROM public.\"payment_transactions\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'payment_types' THEN (SELECT to_jsonb(x) FROM public.\"payment_types\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'pin_attempts' THEN (SELECT to_jsonb(x) FROM public.\"pin_attempts\" x WHERE x.\"key\"=((f.entity_id::jsonb)->>'key') LIMIT 1)\n    WHEN 'pos_settings' THEN (SELECT to_jsonb(x) FROM public.\"pos_settings\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::integer LIMIT 1)\n    WHEN 'product_barcodes' THEN (SELECT to_jsonb(x) FROM public.\"product_barcodes\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid AND public.product_available_in_catalogue(x.product_id,p_branch_id) LIMIT 1)\n    WHEN 'product_categories' THEN (SELECT to_jsonb(x) FROM public.\"product_categories\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'products' THEN (SELECT to_jsonb(x) FROM public.\"products\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid AND public.product_available_in_catalogue(x.id,p_branch_id) LIMIT 1)\n    WHEN 'promotions' THEN (SELECT to_jsonb(x) FROM public.\"promotions\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid AND (x.foc_product_id IS NULL OR public.product_available_in_catalogue(x.foc_product_id,p_branch_id)) LIMIT 1)\n    WHEN 'public_flags' THEN (SELECT to_jsonb(x) FROM public.\"public_flags\" x WHERE x.\"key\"=((f.entity_id::jsonb)->>'key') LIMIT 1)\n    WHEN 'purchase_order_items' THEN (SELECT to_jsonb(x) FROM public.\"purchase_order_items\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'purchase_orders' THEN (SELECT to_jsonb(x) FROM public.\"purchase_orders\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'sale_items' THEN (SELECT to_jsonb(x) FROM public.\"sale_items\" x WHERE x.\"id\"=((f.entity_id::jsonb)->>'id')::uuid LIMIT 1)\n    WHEN 'sales' THEN (SELECT to_jsonb(x)