,v_raw.revision::text,\n   'server_timestamp',to_char(v_raw.server_timestamp AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US')||'0Z');\n  SELECT COALESCE(jsonb_agg(value ORDER BY ordinality),'[]'::jsonb) INTO v_remaining\n   FROM jsonb_array_elements(p_ids) WITH ORDINALITY x(value,ordinality) WHERE ordinality>v_count+1;\n  v_candidate:=jsonb_build_object('protocol','history-rows-v2','policy','branch-history-v1','history_scope',CASE WHEN v_history_company THEN 'company' ELSE 'branch' END,'projection','history-project-v1:a5be97695f3e105ebde271e2f017ddee',\n   'organization_id',p_organization_id,'branch_id',p_branch_id,'terminal_id',p_terminal_id,'keep_commerce',p_keep_commerce,\n   'requested_ids',p_ids,'rows',v_rows||jsonb_build_array(v_wire),'remaining_ids',v_remaining);\n  v_bytes:=octet_length(v_candidate::text);\n  IF v_bytes>p_max_bytes AND v_count>0 THEN EXIT; END IF;\n  IF v_bytes>5242880 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='HISTORY_ROWS_SINGLE_ROW_TOO_LARGE'; END IF;\n  v_result:=v_candidate;v_rows:=v_rows||jsonb_build_array(v_wire);v_count:=v_count+1;\n  IF v_bytes>p_max_bytes THEN EXIT; END IF;\n END LOOP;\n IF v_result IS NULL THEN RAISE EXCEPTION 'HISTORY_ROWS_EMPTY'; END IF;\n PERFORM set_config('response.headers',jsonb_build_array(\n  jsonb_build_object('X-POS-History-Reconcile-Version','2'),\n  jsonb_build_object('X-POS-History-Reconcile-Kind','rows'),\n  jsonb_build_object('X-POS-History-Reconcile-Bytes',octet_length(v_result::text)::text),\n  jsonb_build_object('X-POS-History-Reconcile-Rows',v_count::text))::text,true);\n RETURN v_result;\nEND;\n$function$\n","volatility":"v","definition_md5":"5ab966a9258a8a35fff79fbece0f8b5e","acl_values":["postgres=X/postgres","service_role=X/postgres"],"stored_definition_md5":"6e502cf4dba93421eaced42b13e055c6","old_md5":"6e502cf4dba93421eaced42b13e055c6"}]$history_scope_data$::jsonb;
 helpers constant jsonb := $history_scope_data$[{"signature":"pos_sync_history_company_scope_v1(text,text,text)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_history_company_scope_v1(p_organization_id text,p_branch_id text,p_terminal_id text)\nRETURNS boolean LANGUAGE plpgsql SECURITY INVOKER SET search_path=pg_catalog,public AS $history_scope$\nBEGIN\n PERFORM public.pos_sync_validate_read_scope(p_organization_id,p_branch_id,p_terminal_id);\n RETURN EXISTS(SELECT 1 FROM public.terminal_tokens t WHERE t.id::text=p_terminal_id\n  AND t.platform='pc' AND t.location_id IS NULL AND t.management_sync_enabled\n  AND t.is_claimed AND t.status IN ('active','used') AND t.revoked_at IS NULL);\nEND;\n$history_scope$;","language":"plpgsql","volatility":"v","config":["search_path=pg_catalog, public"],"body":"\nBEGIN\n PERFORM public.pos_sync_validate_read_scope(p_organization_id,p_branch_id,p_terminal_id);\n RETURN EXISTS(SELECT 1 FROM public.terminal_tokens t WHERE t.id::text=p_terminal_id\n  AND t.platform='pc' AND t.location_id IS NULL AND t.management_sync_enabled\n  AND t.is_claimed AND t.status IN ('active','used') AND t.revoked_at IS NULL);\nEND;\n","owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","acl_values":["postgres=X/postgres","service_role=X/postgres"],"definer":false,"strict":false,"returns":"boolean"},{"signature":"pos_sync_history_row_visible_v1(boolean,text,text,text,text,text)","definition":"\u0043REATE OR REPLACE FUNCTION public.pos_sync_history_row_visible_v1(p_company boolean,p_organization_id text,p_branch_id text,p_row_organization_id text,p_scope_type text,p_scope_id text)\nRETURNS boolean LANGUAGE sql IMMUTABLE SECURITY INVOKER SET search_path=pg_catalog AS $history_scope$\n SELECT COALESCE(p_row_organization_id COLLATE \"C\"=p_organization_id COLLATE \"C\" AND\n  (p_company IS TRUE OR (p_scope_type COLLATE \"C\"='BRANCH' AND CASE\n   WHEN p_scope_id COLLATE \"C\" ~ '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$'\n    AND p_branch_id COLLATE \"C\" ~ '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$'\n   THEN lower(p_scope_id)=lower(p_branch_id) ELSE p_scope_id COLLATE \"C\"=p_branch_id COLLATE \"C\" END)),false);\n$history_scope$;","language":"sql","volatility":"i","config":["search_path=pg_catalog"],"body":"\n SELECT COALESCE(p_row_organization_id COLLATE \"C\"=p_organization_id COLLATE \"C\" AND\n  (p_company IS TRUE OR (p_scope_type COLLATE \"C\"='BRANCH' AND CASE\n   WHEN p_scope_id COLLATE \"C\" ~ '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$'\n    AND p_branch_id COLLATE \"C\" ~ '^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$'\n   THEN lower(p_scope_id)=lower(p_branch_id) ELSE p_scope_id COLLATE \"C\"=p_branch_id COLLATE \"C\" END)),false);\n","owner":"postgres","acl":"{postgres=X/postgres,service_role=X/postgres}","acl_values":["postgres=X/postgres","service_role=X/postgres"],"definer":false,"strict":false,"returns":"boolean"}]$history_scope_data$::jsonb;
 shape constant jsonb := $history_scope_data$[{"name":"id","type":"uuid","not_null":true},{"name":"organization_id","type":"text","not_null":true},{"name":"entity_type","type":"text","not_null":true},{"name":"entity_id","type":"text","not_null":true},{"name":"action","type":"text","not_null":true},{"name":"old_value","type":"jsonb","not_null":false},{"name":"new_value","type":"jsonb","not_null":false},{"name":"revision","type":"bigint","not_null":true},{"name":"scope_type","type":"text","not_null":true},{"name":"scope_id","type":"text","not_null":false},{"name":"changed_by","type":"text","not_null":false},{"name":"source_application","type":"text","not_null":true},{"name":"device_id","type":"text","not_null":false},{"name":"terminal_id","type":"text","not_null":false},{"name":"server_timestamp","type":"timestamp with time zone","not_null":true}]$history_scope_data$::jsonb;
 entry jsonb; target jsonb; actual jsonb; fn oid; signature text; definition text; seen_old integer:=0; seen_new integer:=0; added integer:=0;
BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'HISTORY_SCOPE_MIGRATION_OWNER'; END IF;
 PERFORM set_config('search_path','pg_catalog,public',true);
 LOCK TABLE public.change_history IN SHARE ROW EXCLUSIVE MODE NOWAIT;
 SELECT jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull) ORDER BY a.attnum)
 INTO actual FROM pg_attribute a WHERE a.attrelid='public.change_history'::regclass AND a.attnum>0 AND NOT a.attisdropped;
 IF actual IS DISTINCT FROM shape OR NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='public.change_history'::regclass AND relrowsecurity AND pg_get_userbyid(relowner)='postgres')
 OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='public.change_history'::regclass AND contype='p' AND conkey=ARRAY[1]::smallint[] AND convalidated AND NOT condeferrable)
 OR (SELECT count(*) FROM pg_trigger WHERE tgrelid='public.change_history'::regclass AND NOT tgisinternal)<>1
 OR NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.change_history'::regclass AND tgname='change_history_no_change' AND tgenabled='O'
 AND pg_get_triggerdef(oid)='CREATE TRIGGER change_history_no_change BEFORE DELETE OR UPDATE ON public.change_history FOR EACH ROW EXECUTE FUNCTION change_history_immutable()')
 THEN RAISE EXCEPTION 'HISTORY_SCOPE_HISTORY_SHAPE'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(expected) LOOP
  signature:='public.'||(entry->>'signature');fn:=to_regprocedure(signature);
  SELECT value INTO target FROM jsonb_array_elements(desired) WHERE value->>'signature'=entry->>'signature';
  IF fn IS NULL THEN RAISE EXCEPTION 'HISTORY_SCOPE_SOURCE_MISSING'; END IF;
  definition:=replace(pg_get_functiondef(fn),chr(13)||chr(10),chr(10));
  IF md5(definition)<>entry->>'definition_md5' AND (target IS NULL OR md5(definition)<>target->>'definition_md5') THEN RAISE EXCEPTION 'HISTORY_SCOPE_SOURCE_CHANGED'; END IF;
  IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=fn
   AND pg_get_userbyid(p.proowner)=entry->>'owner' AND (SELECT jsonb_agg(v::text ORDER BY v::text) FROM unnest(p.proacl) v)=entry->'acl_values'
   AND to_jsonb(p.proconfig)=entry->'config' AND p.prosecdef=(entry->>'definer')::boolean
   AND p.proisstrict=(entry->>'strict')::boolean AND p.provolatile::text=entry->>'volatility'
   AND l.lanname=entry->>'language' AND pg_get_function_result(p.oid)=entry->>'returns'
   AND p.prokind='f' AND p.proparallel::text=entry->>'parallel' AND p.procost=(entry->>'cost')::real
   AND p.prorows=(entry->>'rows')::real AND p.proleakproof=(entry->>'leakproof')::boolean AND p.prosupport::text=entry->>'support')
  THEN RAISE EXCEPTION 'HISTORY_SCOPE_SOURCE_METADATA'; END IF;
  IF target IS NOT NULL THEN IF md5(definition)=entry->>'definition_md5' THEN seen_old:=seen_old+1;ELSE seen_new:=seen_new+1;END IF;END IF;
 END LOOP;
 FOR entry IN SELECT value FROM jsonb_array_elements(helpers) UNION ALL SELECT value FROM jsonb_array_elements(desired) WHERE value->>'signature' IN ('pos_sync_history_index_v2(text,text,text,text,uuid,uuid,integer,boolean)','pos_sync_history_rows_v2(text,text,text,jsonb,boolean,integer)') LOOP
  fn:=to_regprocedure('public.'||(entry->>'signature'));
  IF fn IS NOT NULL THEN
   added:=added+1;
   IF entry ? 'body' THEN
    IF NOT EXISTS(SELECT 1 FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=fn
     AND replace(p.prosrc,chr(13)||chr(10),chr(10))=entry->>'body' AND pg_get_userbyid(p.proowner)='postgres'
     AND (SELECT jsonb_agg(v::text ORDER BY v::text) FROM unnest(p.proacl) v)=entry->'acl_values' AND to_jsonb(p.proconfig)=entry->'config' AND NOT p.prosecdef AND NOT p.proisstrict
     AND p.provolatile::text=entry->>'volatility' AND l.lanname=entry->>'language' AND pg_get_function_result(p.oid)='boolean'
     AND p.prokind='f' AND NOT p.proleakproof AND p.proparallel='u' AND p.procost=100 AND p.prorows=0 AND p.prosupport=0)
    THEN RAISE EXCEPTION 'HISTORY_SCOPE_EXISTING_HELPER'; END IF;
   ELSE IF md5(replace(pg_get_functiondef(fn),chr(13)||chr(10),chr(10)))<>entry->>'definition_md5'
    OR NOT EXISTS(SELECT 1 FROM pg_proc p WHERE oid=fn AND pg_get_userbyid(proowner)='postgres' AND (SELECT jsonb_agg(v::text ORDER BY v::text) FROM unnest(p.proacl) v)=jsonb_build_array('postgres=X/postgres','service_role=X/postgres'))
    THEN RAISE EXCEPTION 'HISTORY_SCOPE_EXISTING_V2'; END IF;END IF;
  END IF;
 END LOOP;
 IF NOT ((seen_old=7 AND seen_new=0 AND added=0) OR (seen_old=0 AND seen_new=7 AND added=4)) THEN RAISE EXCEPTION 'HISTORY_SCOPE_PARTIAL_INSTALL'; END IF;
 FOR entry IN SELECT value FROM jsonb_array_elements(helpers) LOOP
  EXECUTE entry->>'definition';
  EXECUTE 'REVOKE ALL ON FUNCTION public.'||(entry->>'signature')||' FROM PUBLIC,anon,authenticated,service_role';
  EXECUTE 'GRANT EXECUTE ON FUNCTION public.'||(entry->>'signature')||' TO service_role';
 END LOOP;
 FOR entry IN SELECT value FROM jsonb_array_elements(desired) LOOP
  EXECUTE entry->>'definition';
  IF entry->>'signature' IN ('pos_sync_history_index_v2(text,text,text,text,uuid,uuid,integer,boolean)','pos_sync_history_rows_v2(text,text,text,jsonb,boolean,integer)') THEN
   EXECUTE 'REVOKE ALL ON FUNCTION public.'||(entry->>'signature')||' FROM PUBLIC,anon,authenticated,service_role';
   EXECUTE 'GRANT EXECUTE ON FUNCTION public.'||(entry->>'signature')||' TO service_role';
  END IF;
  IF md5(replace(pg_get_functiondef(to_regprocedure('public.'||(entry->>'signature'))),chr(13)||chr(10),chr(10)))<>entry->>'definition_md5' THEN RAISE EXCEPTION 'HISTORY_SCOPE_READBACK'; END IF;
 END LOOP;
END;
$history_scope_upgrade$;
